import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";
import { PillLegacyComponent } from "../../lib/pill-legacy.component";

@Component({
    selector: "app-feature-1",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent, PillLegacyComponent ],
    templateUrl: "./feature-1.component.html"
})
export class Feature001Component {
---
<app-card heading="Feature 1" [disableTooltip]="true">
  <p class="hint">Set disableTooltip on a pill to hide its hint.</p>
  <app-pill [disableTooltip]='true' label='Plain'/>
  <app-pill  variant="success"  [disableTooltip]="!isActive"  label="Active"/>
  <app-pill [disableTooltip]="count > 3" [label]="title" variant="info" />
  <app-pill [variant]="isActive ? 'success' : 'warning'" label="Multi-line" [disableTooltip]="isActive"></app-pill>
  @if (isActive) {
    <app-pill-legacy label="Legacy" variant="info" [disableTooltip]="true" />
  }
  @if (disableTooltip) {
    <small>Own flag, unrelated to the pill input</small>
  }
</app-card>
